function solve(s) {
  const numSt = [], strSt = [];
  let cur = '', num = 0;
  for (const ch of s) {
    if (ch >= '0' && ch <= '9') num = num * 10 + (ch.charCodeAt(0) - 48);
    else if (ch === '[') { numSt.push(num); strSt.push(cur); num = 0; cur = ''; }
    else if (ch === ']') { const k = numSt.pop(); cur = strSt.pop() + cur.repeat(k); }
    else cur += ch;
  }
  return cur;
}
